mapper.update:
UPDATE flow_event_outbox SET status = 'DELIVERED', delivered_at = #{now}, lease_token = NULL,
    lease_until = NULL WHERE event_id = #{eventId} AND status = 'PROCESSING' AND lease_token = #{token}
    AND lease_until > #{now}

UPDATE flow_event_outbox SET status = #{status}, retry_count = #{retryCount}, total_failures = total_failures + 1,
    next_attempt_at = #{nextAttemptAt}, last_error = #{lastError}, lease_token = NULL, lease_until = NULL
WHERE event_id = #{eventId} AND lease_token = #{token}
